import sys
def palindromepair(arr, N):
    def is_palindrome(s):
        return s == s[::-1]
    seen = set()
    for word in arr:
        for i in range(len(word) + 1):
            prefix, suffix = word[:i], word[i:]
            if is_palindrome(prefix) and suffix[::-1] in seen:
                return True
            if is_palindrome(suffix) and prefix[::-1] in seen:
                return True
        seen.add(word)
    return False

input = sys.stdin.read().strip().split()
N = int(input[0])
arr = input[1:]
print('1' if palindromepair(arr, N) else '0')
